    public void handlePositions(Client client, Object message)
    {
        //
        //     {
        //         "e": "ACCOUNT_UPDATE",
        //         "T": 1768551627708,
        //         "E": 1768551627710,
        //         "a": {
        //             "B": [
        //                 {
        //                     "a": "USDT",
        //                     "wb": "39.41184271",
        //                     "cw": "39.41184271",
        //                     "bc": "0"
        //                 }
        //             ],
        //             "P": [
        //                 {
        //                     "s": "ETHUSDT",
        //                     "pa": "0",
        //                     "ep": "0.00000000",
        //                     "cr": "-0.59070000",
        //                     "up": "0",
        //                     "mt": "isolated",
        //                     "iw": "0",
        //                     "ps": "BOTH",
        //                     "ma": "USDT"
        //                 }
        //             ],
        //             "m": "ORDER"
        //         }
        //     }
        //
        Object messageHash = "positions";
        if (Helpers.isTrue(Helpers.isEqual(this.positions, null)))
        {
            this.positions = new ArrayCache.ArrayCacheBySymbolBySide();
        }
        Object cache = this.positions;
        Object data = this.safeDict(message, "a", new java.util.HashMap<String, Object>() {{}});
        Object rawPositions = this.safeList(data, "P", new java.util.ArrayList<Object>(java.util.Arrays.asList()));
        Object newPositions = new java.util.ArrayList<Object>(java.util.Arrays.asList());
        for (var i = 0; Helpers.isLessThan(i, Helpers.getArrayLength(rawPositions)); i++)
        {
            Object rawPosition = Helpers.GetValue(rawPositions, i);
            Object position = this.parseWsPosition(rawPosition);
            Object timestamp = this.safeInteger(message, "E");
            Helpers.addElementToObject(position, "timestamp", timestamp);
            Helpers.addElementToObject(position, "datetime", this.iso8601(timestamp));
            ((java.util.List<Object>)newPositions).add(position);
            Helpers.callDynamically(cache, "append", new Object[]{position});
        }
        Object messageHashes = this.findMessageHashes(client, messageHash);
        if (!Helpers.isTrue(this.isEmpty(messageHashes)))
        {
            for (var i = 0; Helpers.isLessThan(i, Helpers.getArrayLength(newPositions)); i++)
            {
                Object position = Helpers.GetValue(newPositions, i);
                Object symbol = Helpers.GetValue(position, "symbol");
                Object symbolMessageHash = Helpers.add(Helpers.add(messageHash, "::"), symbol);
                client.resolve(position, symbolMessageHash);
            }
            client.resolve(newPositions, "positions");
        }
    }

    public Object parseWsPosition(Object position, Object... optionalArgs)
    {
        //
        //     {
        //         "s": "BTCUSDT", // Symbol
        //         "pa": "0", // Position Amount
        //         "ep": "0.00000", // Entry Price
        //         "cr": "200", // (Pre-fee) Accumulated Realized
        //         "up": "0", // Unrealized PnL
        //         "mt": "isolated", // Margin Type
        //         "iw": "0.00000000", // Isolated Wallet (if isolated position)
        //         "ps": "BOTH" // Position Side
        //     }
        //
        Object market = Helpers.getArg(optionalArgs, 0, null);
        Object marketId = this.safeString(position, "s");
        Object contracts = this.safeString(position, "pa");
        Object contractsAbs = Precise.stringAbs(this.safeString(position, "pa"));
        Object positionSide = this.safeStringLower(position, "ps");
        Object hedged = true;
        if (Helpers.isTrue(Helpers.isEqual(positionSide, "both")))
        {
            hedged = false;
            if (!Helpers.isTrue(Precise.stringEq(contracts, "0")))
            {
                if (Helpers.isTrue(Precise.stringLt(contracts, "0")))
                {
                    positionSide = "short";
                } else
                {
                    positionSide = "long";
                }
            }
        }
        final Object finalPositionSide = positionSide;
        final Object finalHedged = hedged;
        return this.safePosition(new java.util.HashMap<String, Object>() {{
            put( "info", position );
            put( "id", null );
            put( "symbol", Aster.this.safeSymbol(marketId, null, null, "swap") );
            put( "notional", null );
            put( "marginMode", Aster.this.safeString(position, "mt") );
            put( "liquidationPrice", null );
            put( "entryPrice", Aster.this.safeNumber(position, "ep") );
            put( "unrealizedPnl", Aster.this.safeNumber(position, "up") );
            put( "percentage", null );
            put( "contracts", Aster.this.parseNumber(contractsAbs) );
            put( "contractSize", null );
            put( "markPrice", null );
            put( "side", finalPositionSide );
            put( "hedged", finalHedged );
            put( "timestamp", null );
            put( "datetime", null );
            put( "maintenanceMargin", null );
            put( "maintenanceMarginPercentage", null );
            put( "collateral", null );
            put( "initialMargin", null );
            put( "initialMarginPercentage", null );
            put( "leverage", null );
            put( "marginRatio", null );
        }});
    }

    /**
     * @method
     * @name aster#watchOrders
     * @description watches information on multiple orders made by the user
     * @see https://asterdex.github.io/aster-api-website/spot-v3/websocket-account-info/#payload-order-update
     * @see https://asterdex.github.io/aster-api-website/futures-v3/user-data-streams/#event-order-update
     * @param {string} [symbol] unified market symbol of the market orders were made in
     * @param {int} [since] the earliest time in ms to fetch orders for
     * @param {int} [limit] the maximum number of order structures to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.type] 'spot' or 'swap', default is 'spot' if symbol is not provided
     * @returns {object[]} a list of [order structures]{@link https://docs.ccxt.com/?id=order-structure}
     */
    public java.util.concurrent.CompletableFuture<Object> watchOrders(Object... optionalArgs)
    {

        return java.util.concurrent.CompletableFuture.supplyAsync(() -> {

            Object symbol = Helpers.getArg(optionalArgs, 0, null);
            Object since = Helpers.getArg(optionalArgs, 1, null);
            Object limit = Helpers.getArg(optionalArgs, 2, null);
            Object parameters = Helpers.getArg(optionalArgs, 3, new java.util.HashMap<String, Object>() {{}});
            if (Helpers.isTrue(Helpers.isEqual(this.markets, null)))
            {
                (this.loadMarkets()).join();
            }
            Object market = null;
            if (Helpers.isTrue(!Helpers.isEqual(symbol, null)))
            {
                market = this.market(symbol);
                symbol = Helpers.GetValue(market, "symbol");
            }
            Object messageHash = "orders";
            Object type = null;
            var typeparametersVariable = this.handleMarketTypeAndParams("watchOrders", market, parameters, type);
            type = ((java.util.List<Object>) typeparametersVariable).get(0);
            parameters = ((java.util.List<Object>) typeparametersVariable).get(1);
            (this.authenticate(type, parameters)).join();
            if (Helpers.isTrue(!Helpers.isEqual(market, null)))
            {
                messageHash = Helpers.add(messageHash, Helpers.add("::", symbol));
            }
            Object url = this.getPrivateUrl(type);
            Client client = this.client(url);
            this.setBalanceCache(client, type);
            Object orders = (this.watchMultiple(url, new java.util.ArrayList<Object>(java.util.Arrays.asList(messageHash)), null, new java.util.ArrayList<Object>(java.util.Arrays.asList(type)), null)).join();
            if (Helpers.isTrue(this.newUpdates))
            {
                limit = Helpers.callDynamically(orders, "getLimit", new Object[]{symbol, limit});
            }
            return this.filterBySymbolSinceLimit(orders, symbol, since, limit, true);
        });

    }

